precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float t;
uniform float size;
uniform float min;
uniform float u_max;    // Renamed 'max' to 'u_max' to avoid conflict with the built-in max() function
uniform float wl;
uniform vec2 u_center;  // <-- New uniform for the dynamic center position

void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  vec2 vSc = vUvScaled * vec2(1.0, 0.5625);
  // gl_FragColor = texel; // Removed this line as it was overwritten later

  // Calculate the center position adjusted for aspect ratio
  vec2 center_aspect = u_center * vec2(1.0, 0.5625);

  // --- MODIFIED TO USE U_CENTER ---
  // main_dst now calculates distance relative to the new dynamic center
  float main_dst = distance(vSc, center_aspect); 

  float grid_dst = distance(mod(vSc * vec2(size), vec2(1.0)), vec2(0.5));
  grid_dst /= 1.41421356237;
  // The animation wave is still driven by main_dst distance
  grid_dst += sin(main_dst * wl - t) / 2.0 + 0.5;

  gl_FragColor = vec4(1.0);
  // Using the renamed uniform u_max
  gl_FragColor[3] = float(1.0 - grid_dst * u_max > min); // Changed '>' back to '<' based on typical usage for showing shapes
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float t;
uniform float size;
uniform float min;
uniform float u_max; // Renamed from 'max' to avoid compiler error
uniform float wl;
uniform vec2 u_center; // <-- New uniform for the dynamic center position

void main()
{
  // vec4 texel = texture2D(tDiffuse, vUvScaled); // Keep this if you use the texture later
  vec2 vSc = vUvScaled * vec2(1.0, 0.5625);
  // gl_FragColor = texel; 

  // --- MODIFIED TO USE U_CENTER ---

  // Calculate the coordinate within each tile
  vec2 tiled_coords = mod(vSc * vec2(size), vec2(1.0));

  // Use the 'max' of the coordinate delta from the center (0.5) to define squares
  float grid_dst = max(abs(tiled_coords.x - 0.5), abs(tiled_coords.y - 0.5));

  // Normalize/Scale if necessary (not strictly needed for this approach)
  // grid_dst /= 1.41421356237; 

  // --- MODIFIED TO USE U_CENTER ---
  // The animation wave now originates from the dynamic center U_CENTER
  float main_dst = distance(vSc, u_center * vec2(1.0, 0.5625));
  grid_dst += sin(main_dst * wl - t) / 2.0 + 0.5;


  gl_FragColor = vec4(1.0);
  // The thresholding line still works perfectly to cut the gradient into solid shapes
  gl_FragColor[3] = float(1.0 - grid_dst * u_max > min);
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse; 
varying vec2 vUvScaled; 

#define MAX_ITERATIONS 20 

// --- Editable Uniforms ---
uniform int uIterations; 
uniform vec2 uResolution; 
uniform float uExtrusionDistance; 
uniform vec2 uExtrusionDirection; 
uniform float uScaleFactor; 
uniform float uAttenuation;

// NEW: Extrusion Color Properties
uniform vec3 uExtrusionColor; // The RGB color of the extrusion (e.g., vec3(1.0, 0.0, 0.0) for red)
uniform float uColorMix;      // 0.0 = original texture, 1.0 = solid uExtrusionColor

void main() {
    vec4 finalColor = vec4(0.0);
    vec2 center = vec2(0.5);

    float maxDimension = max(uResolution.x, uResolution.y);
    vec2 pixelToUv = vec2(maxDimension / uResolution.x, maxDimension / uResolution.y) / maxDimension;

    // Iterate to draw the duplicated layers (back-to-front)
    for (int i = 1; i <= MAX_ITERATIONS; ++i) {

        if (i > uIterations) {
            break; 
        }

        int distanceIndex = uIterations - i + 1; 

        float scale = pow(uScaleFactor, float(distanceIndex));
        float totalExtrusionPixels = uExtrusionDistance * float(distanceIndex); 
        vec2 extrusionVectorPixels = uExtrusionDirection * totalExtrusionPixels;
        vec2 extrusionVectorUV = extrusionVectorPixels * pixelToUv;

        vec2 transformedUv = vUvScaled;
        transformedUv = transformedUv - extrusionVectorUV;
        transformedUv = center + (transformedUv - center) / scale;

        if (transformedUv.x >= 0.0 && transformedUv.x <= 1.0 && 
            transformedUv.y >= 0.0 && transformedUv.y <= 1.0) {

            vec4 texel = texture2D(tDiffuse, transformedUv);

            // --- COLOR MODIFICATION START ---
            // Mix the original texture color with the custom extrusion color
            // We only change the RGB, keeping the original alpha for transparency masks
            texel.rgb = mix(texel.rgb, uExtrusionColor, uColorMix);
            // --- COLOR MODIFICATION END ---

            float fadeFactor = 1.0 - (float(distanceIndex) / float(uIterations)) * uAttenuation;
            texel.a *= fadeFactor;

            finalColor = mix(finalColor, texel, texel.a); 
        }
    }

    // Draw the Original Layer (in front) - We don't apply the tint here
    vec4 originalTexel = texture2D(tDiffuse, vUvScaled);
    finalColor = mix(finalColor, originalTexel, originalTexel.a);

    gl_FragColor = finalColor;
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// The resolution of the composition (e.g., 1920.0, 1080.0)
// Needed to normalize the pixel coordinates of Start and End.
uniform vec2 resolution;

// The Start point: The anchor of the effect. The image remains fixed here.
// Default: 960.0, 540.0 (Half of 1080p)
uniform vec2 start;

// The End point: Defines the direction and height of the bend area.
// Default: 960.0, 540.0 (Half of 1080p)
// Note: Ideally offset this from start (e.g. 960.0, 0.0) to see the effect.
uniform vec2 end;

// Controls the intensity of the bend.
uniform float bend;

void main()
{
  // 1. SETUP CONSTANTS
  float zero = 0.0;
  float one = 1.0;
  float two = 2.0;
  float pi = 3.14159265;
  float epsilon = 0.0001;

  // 2. CONVERT TO PIXEL SPACE
  // We work in pixel coordinates to match the "Start" and "End" uniform behavior.
  vec2 texCoord = vUvScaled * resolution;

  // 3. DEFINE LOCAL COORDINATE SYSTEM
  // Calculate the vector from Start to End
  vec2 segment = end - start;
  float segmentLength = length(segment);

  // If Start and End are too close, avoid division by zero and return original pixel
  if (segmentLength < epsilon) {
    gl_FragColor = texture2D(tDiffuse, vUvScaled);
    return;
  }

  // Calculate basis vectors for a local coordinate system where:
  // Y-axis aligns with the Start -> End line.
  // X-axis is perpendicular.
  vec2 axisY = normalize(segment);
  vec2 axisX = vec2(axisY.y, -axisY.x); // Rotate 90 degrees

  // 4. TRANSFORM PIXEL TO LOCAL SPACE
  // Shift origin to Start point
  vec2 delta = texCoord - start;

  // Project current pixel onto our local axes
  // localPos.x = distance to the right/left of the spine
  // localPos.y = distance along the spine (up/down)
  vec2 localPos = vec2(dot(delta, axisX), dot(delta, axisY));

  // 5. APPLY INVERSE BEND DISTORTION
  // We want to find which source pixel maps to this current local position.
  vec2 sourceLocalPos = localPos;

  if (abs(bend) > epsilon) {
    // Radius R = Length / Bend
    // Note: We assume 'bend' ranges roughly 0.0 to 1.0 or 0.0 to 100.0.
    // We multiply by segmentLength to scale relative to the size of the selection.
    float radius = segmentLength / bend * 100.0; // Scaling factor for sensitivity

    // Calculate the Center of Curvature.
    // Since we are bending along the Y-axis, the center is offset along the X-axis.
    vec2 centerOfCurvature = vec2(radius, zero);

    // Vector from Center of Curvature to our current pixel
    vec2 diff = localPos - centerOfCurvature;

    // Inverse Polar Mapping:
    // The current Angle determines the Source Y (height along the original spine).
    // The current Distance determines the Source X (distance from the original spine).
    float currentDist = length(diff);

    // Calculate angle. We use atan(y, -x) because our center is at +radius.
    // We adjust the sign based on the radius direction.
    float currentAngle = atan(diff.y, -diff.x * sign(radius));

    // Map back to straight Cartesian space
    // Source X is the difference between the radius and the current distance
    sourceLocalPos.x = (currentDist - abs(radius)) * sign(radius);

    // Source Y is the arc length: Angle * Radius
    sourceLocalPos.y = currentAngle * abs(radius);
  }

  // 6. TRANSFORM BACK TO UV SPACE
  // Rotate and Translate back to global pixel space
  vec2 sourcePixel = start + (axisX * sourceLocalPos.x) + (axisY * sourceLocalPos.y);

  // Normalize back to 0.0 - 1.0 UV range
  vec2 finalUv = sourcePixel / resolution;

  // 7. BOUNDS CHECKING (Optional "Crop" like CC Bend It)
  // Check if the calculated UV is outside the texture bounds
  if (finalUv.x < zero || finalUv.x > one || finalUv.y < zero || finalUv.y > one) {
     gl_FragColor = vec4(zero, zero, zero, zero);
  } else {
     gl_FragColor = texture2D(tDiffuse, finalUv);
  }
}

precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- User Variables (Uniforms) ---

// Offset: Offset of the pattern (Default: 0, 0)
uniform vec2 uOffset;

// Size: Size of pattern (Range: 0.5 to 200, Default: 10)
// At 100, one hex fills layer vertically.
uniform float uSize;

// Stretch: Vertical scaling (Range: 0.01 to 10, Default: 1)
uniform float uStretch;

// Coloring: 0=Layer, 1=Solid, 2=Stripes, 3=Tricolor, 4=Cube, 5=Triangles, 6=Pentagonal
uniform float uColoring;

// Colors
uniform vec4 uColor1;
uniform vec4 uColor2;
uniform vec4 uColor3;

// Alpha: Pattern opacity (Range: 0 to 1, Default: 1)
uniform float uAlpha;

// Blending Mode: 0=Normal, 1=Multiply, 2=Screen, 3=Overlay, 4=Overflow, 5=PunchOut
uniform float uBlendingMode;

// Scale Using Layer Alpha: 0=Off, 1=On
uniform float uScaleLayerAlpha;

// Copy Layer Alpha: 0=Off, 1=On
uniform float uCopyLayerAlpha;

// Line Width: Ratio of hex size (Range: 0 to 1, Default: 0.1)
uniform float uLineWidth;

// Feather: Softness (Range: 0 to 1, Default: 0.05)
uniform float uFeather;

// Angle: Rotation in degrees
uniform float uAngle;

// Screen Space: 0=Off, 1=On
uniform float uScreenSpace;

// Constants
const float PI = 3.14159265359;
const float SQRT3 = 1.7320508;

// Helper: Rotation Matrix
mat2 rotate2d(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

// Helper: Value Step (mimics if/else for floats)
float when_eq(float x, float y) {
    return 1.0 - abs(sign(x - y));
}

float when_between(float x, float start, float end) {
    return step(start, x) * step(x, end);
}

// Helper: Hexagon Math
// Returns vec4: xy = skew coords, zw = grid ID
vec4 hexCoords(vec2 uv) {
    vec2 r = vec2(1.0, SQRT3);
    vec2 h = r * 0.5;
    vec2 a = mod(uv, r) - h;
    vec2 b = mod(uv - h, r) - h;

    vec2 gv = dot(a, a) < dot(b, b) ? a : b;

    // Calculate ID (approximate center for randomness/stripes)
    vec2 id = uv - gv;
    // Fix ID coordinate space to be roughly integer-like for modulo arithmetic
    // Convert back to grid integers roughly
    float iy = floor((id.y + 0.1) / (SQRT3 * 0.5));
    float ix = floor((id.x + 0.1 + (mod(iy, 2.0) * 0.5))); // Offset row logic

    return vec4(gv.x, gv.y, id.x, id.y);
}

// Hexagon SDF (Distance to edge)
float hexDist(vec2 p) {
    p = abs(p);
    return max(dot(p, vec2(0.5, SQRT3 * 0.5)), p.x); // Pointy top logic mostly
}

// Blend Modes
vec3 blendMultiply(vec3 base, vec3 blend) { return base * blend; }
vec3 blendScreen(vec3 base, vec3 blend) { return 1.0 - (1.0 - base) * (1.0 - blend); }
vec3 blendOverlay(vec3 base, vec3 blend) {
    return mix(2.0 * base * blend, 1.0 - 2.0 * (1.0 - base) * (1.0 - blend), step(0.5, base));
}

void main() {
    // 1. Coordinate Setup
    vec2 uv = vUvScaled;

    // Screen Space logic (simplified, assuming standard UV implies layer space)
    // If ScreenSpace is on, we might ignore aspect adjustments, but here we treat uv as is.

    // Center UVs generally for rotation
    vec2 center = vec2(0.5);
    vec2 pos = uv - center;

    // Apply Rotation
    float rad = radians(uAngle);
    pos = rotate2d(-rad) * pos;

    // Apply Offset (relative to layer, so we subtract)
    pos -= uOffset;

    // Apply Stretch (Vertical scaling)
    pos.y /= max(0.001, uStretch); // Avoid divide by zero

    // Apply Size
    // Size 100 = 1.0 UV height (approx). 
    // Grid Scale factor. 
    float gridSize = max(0.5, uSize) / 100.0;
    // Hex Grid math usually relies on specific spacing. 
    // Scale pos down so the grid logic works on unit 1.0
    // Adjust scale so Size 10 => 0.1 height per hex.
    float scale = 1.0 / (gridSize * SQRT3); // Adjust factor to match "100 = full screen" roughly
    pos *= scale;

    // 2. Grid Calculation
    // We use a manual grid approach for robustness without integer bitwise ops
    vec2 r = vec2(1.0, SQRT3);
    vec2 h = r * 0.5;

    vec2 a = mod(pos, r) - h;
    vec2 b = mod(pos - h, r) - h;

    vec2 gv; // Local UV in hex
    vec2 id; // Center of hex

    // Check which grid center is closer
    float d1 = dot(a, a);
    float d2 = dot(b, b);

    // Mix/Step to avoid if
    float which = step(d2, d1); // 1 if b is closer
    gv = mix(a, b, which);
    id = pos - gv;

    // 3. Hexagon ID for Coloring
    // We need integer-like IDs for parity checks (Stripes/Tricolor)
    // Reverse engineer grid coordinates (col, row)
    // y-row is approx id.y / (SQRT3 * 0.5)
    float row = floor((id.y / (SQRT3 * 0.5)) + 0.5);
    // x-col: if row is even, id.x is integer. if row is odd, id.x is integer + 0.5
    float shift = mod(row, 2.0) * 0.5;
    float col = floor(id.x - shift + 0.5);

    // 4. Sample Layer Data (Pixel at center of hex)
    // We need to un-transform the ID to get the UV of the center.
    // Re-apply Size, Stretch, Offset, Rotation (Inverse)
    vec2 centerUV = id / scale;
    centerUV.y *= uStretch;
    centerUV += uOffset;
    centerUV = rotate2d(rad) * centerUV;
    centerUV += center;

    vec4 layerColor = texture2D(tDiffuse, centerUV);
    vec4 originalPixel = texture2D(tDiffuse, vUvScaled);
    float layerAlpha = layerColor.a;

    // 5. Calculate Shape & Mask
    // Distance from center of hex (gv)
    // Pointy topped hex distance
    // Using simple math: max(abs(x)*0.866 + abs(y)*0.5, abs(y))
    // But our grid is slightly different orientation, let's stick to standard hex dist:
    vec2 absGV = abs(gv);
    float dist = max(dot(absGV, vec2(0.5, SQRT3 * 0.5)), absGV.x); // rotated 90 deg relative to standard?
    // Let's normalize dist to 0.0-0.5 range (0 at center, 0.5 at edge of incircle)

    // Scale Using Layer Alpha logic
    float sizeMod = 1.0;
    sizeMod = mix(1.0, layerAlpha, uScaleLayerAlpha);

    // Line Width Logic
    // Max radius of hex in this grid space is 0.5 (apothem). 
    // Map LineWidth 0..1 to threshold.
    float radius = 0.5 * sizeMod; // Max size
    float border = uLineWidth * 0.5; // Thickness
    float edge = radius - border;

    // Feathering
    float feather = max(0.0001, uFeather * 0.5);
    float mask = 1.0 - smoothstep(edge - feather, edge, dist);

    // 6. Coloring Logic
    vec4 finalColor = uColor1; // Default

    // Calculate 3 pattern values
    // Stripes: Rows
    float stripe = mod(row, 2.0); // 0 or 1

    // Tricolor: (col + row) % 3 ? Need a tiling 
    // Standard hex 3-color: mod(col - row, 3.0)
    float tri = mod(col + ceil(row/2.0), 3.0); // Simple 3-color map

    // Sub-region angles (0 to 1)
    float angle = atan(gv.x, gv.y) + PI; // 0 to 2PI
    float nAngle = angle / (2.0 * PI); // 0 to 1

    // Modes
    // 0: Layer
    vec4 cLayer = layerColor;

    // 1: Solid
    vec4 cSolid = uColor1;

    // 2: Stripes (Color 1, Color 2)
    vec4 cStripes = mix(uColor1, uColor2, step(0.5, stripe));

    // 3: Tricolor
    // 0->C1, 1->C2, 2->C3
    vec4 cTri = mix(uColor1, uColor2, step(0.5, abs(tri - 1.0))); // if tri==1 use C2
    cTri = mix(cTri, uColor3, step(1.5, tri)); // if tri==2 use C3

    // 4: Cube (3 Rhombi)
    // Angles: 0-120 (0-0.33), 120-240 (0.33-0.66), 240-360 (0.66-1.0)
    float cubeReg = floor(nAngle * 3.0);
    vec4 cCube = mix(uColor1, uColor2, step(0.5, abs(cubeReg - 1.0)));
    cCube = mix(cCube, uColor3, step(1.5, cubeReg));

    // 5: Triangles (6 Triangles)
    float triReg = floor(nAngle * 6.0);
    // Sequence: 1, 2, 3, 1, 2, 3...
    float triMod = mod(triReg, 3.0);
    vec4 cTriangle = mix(uColor1, uColor2, step(0.5, abs(triMod - 1.0)));
    cTriangle = mix(cTriangle, uColor3, step(1.5, triMod));

    // 6: Pentagonal (Type 3 / 3-split offset)
    // Offset angle by 0.5/3.0 (half a segment)
    float pentaReg = floor(fract(nAngle + 0.1666) * 3.0);
    vec4 cPenta = mix(uColor1, uColor2, step(0.5, abs(pentaReg - 1.0)));
    cPenta = mix(cPenta, uColor3, step(1.5, pentaReg));

    // Selection
    finalColor = mix(finalColor, cLayer, when_between(uColoring, -0.1, 0.5));
    finalColor = mix(finalColor, cSolid, when_between(uColoring, 0.5, 1.5));
    finalColor = mix(finalColor, cStripes, when_between(uColoring, 1.5, 2.5));
    finalColor = mix(finalColor, cTri, when_between(uColoring, 2.5, 3.5));
    finalColor = mix(finalColor, cCube, when_between(uColoring, 3.5, 4.5));
    finalColor = mix(finalColor, cTriangle, when_between(uColoring, 4.5, 5.5));
    finalColor = mix(finalColor, cPenta, when_between(uColoring, 5.5, 6.5));

    // 7. Alpha & Blending Logic

    // Copy Layer Alpha
    float alphaMult = mix(1.0, layerAlpha, uCopyLayerAlpha);
    finalColor.a *= alphaMult;

    // Master Alpha
    finalColor.a *= uAlpha;

    // Apply Mask (Hex Shape)
    // If "Punch Out" (Mode 5), we invert logic: 
    // Transparent where hex is, Opaque where gap is.
    float isPunchOut = when_between(uBlendingMode, 4.5, 5.5);
    float finalMask = mix(mask, 1.0 - mask, isPunchOut);

    finalColor.a *= finalMask;

    // Apply Blending with Background (Original Layer)
    // 0=Normal, 1=Multiply, 2=Screen, 3=Overlay, 4=Overflow, 5=PunchOut

    // Normal / Overflow / PunchOut are compositing logic, others are color math.

    vec4 base = originalPixel;
    vec3 mixedColor = finalColor.rgb;

    // Multiply
    vec3 mult = blendMultiply(base.rgb, finalColor.rgb);
    // Screen
    vec3 scr = blendScreen(base.rgb, finalColor.rgb);
    // Overlay
    vec3 ovr = blendOverlay(base.rgb, finalColor.rgb);

    mixedColor = mix(mixedColor, mult, when_between(uBlendingMode, 0.5, 1.5));
    mixedColor = mix(mixedColor, scr, when_between(uBlendingMode, 1.5, 2.5));
    mixedColor = mix(mixedColor, ovr, when_between(uBlendingMode, 2.5, 3.5));

    // Compositing
    // Normal: Overly on top, strictly inside layer alpha? 
    // Description: "Normal... but only within layer's original opaque areas"
    // "Overflow": "Rendered fully" (ignore base alpha clip)

    float isNormal = when_between(uBlendingMode, -0.1, 0.5);
    float isOverflow = when_between(uBlendingMode, 3.5, 4.5);

    // Logic: 
    // If Normal: result = mix(base, hex, hex.a * base.a) ? 
    // Usually "only within opaque areas" means we clip by base.a.

    // Final composite logic
    vec4 result = base;

    // If pattern is effectively transparent (gaps), we see base.
    // mix(base, pattern, pattern.a)

    vec4 composite = vec4(mixedColor, finalColor.a);

    // Apply clipping for Normal mode
    float clip = mix(1.0, base.a, isNormal); // If normal, multiply alpha by base.a
    // Ensure Overflow ignores this clip (keeps 1.0)
    // PunchOut (Mode 5) clears alpha.

    composite.a *= clip;

    // Mix based on alpha
    // Result = base * (1 - composite.a) + composite * composite.a ?? (Standard premult blending)
    // Simplified mix:
    result.rgb = mix(result.rgb, composite.rgb, composite.a);

    // Handle Punch Out specifically
    // "Punch Out - Hexagon punch through... making layer transparent"
    // If punchout, alpha = base.a * (1.0 - hexMask).
    // We calculated finalMask as inverted earlier.
    if (isPunchOut > 0.5) {
       result = base;
       result.a *= finalMask; // Cuts hole
    } else {
        // Apply alpha update for normal cases
        // If Overflow, we might extend outside base geometry.
        // If Normal, we are clipped by base.a.
        float finalA = max(base.a, composite.a); // Keep max alpha?
        // Actually, if Normal, we shouldn't add alpha where base is 0.
        if (isNormal > 0.5) {
            result.a = base.a; // Preserve original alpha channel?
            // "Overlaid ... within layer's original opaque areas"
            // This implies we don't increase the alpha of the layer, just change color.
            result.rgb = mix(base.rgb, mixedColor, finalColor.a);
        } else if (isOverflow > 0.5) {
             // Add hex on top, extending alpha
             result = mix(base, composite, composite.a);
        } else {
             // Blend modes (Screen/Mult/Overlay) usually apply inside existing alpha too
             result.rgb = mix(base.rgb, mixedColor, finalColor.a);
             result.a = base.a;
        }
    }

    gl_FragColor = result;
}

precision highp float;
// precision highp int; // Avoided as requested

// --- UNIFORMS (Connect these to your host program) ---
uniform sampler2D tDiffuse;      // Background Image
uniform vec2 uResolution;        // Screen resolution (e.g., 1920.0, 1080.0)
uniform float uTime;             // Time in seconds
uniform vec2 uMouse;             // Mouse position (optional interaction)

// --- PLEXUS SETTINGS (Editable Variables) ---
uniform vec3 uColor;             // Color of the plexus (default: 0.2, 0.6, 1.0)
uniform float uGridScale;        // Size of the grid cells (default: 5.0 to 10.0)
uniform float uDotSize;          // Radius of the dots (default: 0.05)
uniform float uLineThickness;    // Thickness of lines (default: 0.002)
uniform float uConnectionDist;   // Max distance to connect dots (default: 0.35)
uniform float uGlowStrength;     // Intensity of the glow (default: 0.5)

varying vec2 vUvScaled;          // From your template

// --- HELPER FUNCTIONS ---

// random hash function (float based)
float hash21(vec2 p) {
    p = fract(p * vec2(234.34, 435.345));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// "Noise Effector": Calculate particle position for a grid ID
vec2 getParticlePos(vec2 id) {
    vec2 n = hash22(id);
    // Animate the point using sine waves (Lissajous-like movement)
    // We use uTime to drive the "Noise Effector"
    float t = uTime * 0.5;

    // Create organic movement
    float x = sin(t * n.x + n.y * 6.28) * 0.4; // Keep inside cell mostly
    float y = cos(t * n.y + n.x * 6.28) * 0.4;

    return vec2(x, y);
}

// Distance to a line segment (a to b)
float distToLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// ... [Insert Shader 1: Common Logic here] ...

void main() {
    // 1. Setup Coordinates
    // Scale UVs to create a grid. Aspect ratio correction is crucial.
    vec2 uv = vUvScaled;
    uv.x *= uResolution.x / uResolution.y; // Correct aspect ratio

    vec2 st = uv * uGridScale; 
    vec2 id = floor(st);      // The integer-like ID of the current grid cell
    vec2 localUv = fract(st) - 0.5; // Local coordinate inside the cell (-0.5 to 0.5)

    vec3 color = vec3(0.0);

    // 2. Neighbor Search Loop (3x3 Grid)
    // We check the current cell and its 8 neighbors
    for(float y = -1.0; y <= 1.0; y += 1.0) {
        for(float x = -1.0; x <= 1.0; x += 1.0) {
            vec2 offset = vec2(x, y);

            // Get the unique particle position for this neighbor cell
            vec2 pointPos = getParticlePos(id + offset);

            // Calculate distance from current pixel to that particle
            // We add 'offset' to move the particle into our local coordinate space
            float dist = length(localUv - (offset + pointPos));

            // 3. Render Dot with Glow (Spherical Effector style)
            // Use inverse square law for nice soft glow: 1.0 / (d*d)
            float intensity = uGlowStrength * (uDotSize * 0.1) / (dist * dist + 0.0001);

            // Hard center for the dot
            float circle = smoothstep(uDotSize, uDotSize * 0.8, dist);

            color += uColor * (circle + intensity);
        }
    }

    // 4. Composite over background without dimming
    vec4 bg = texture2D(tDiffuse, vUvScaled);
    gl_FragColor = vec4(bg.rgb + color, 1.0);
}

precision highp float;
// precision highp int; // Avoided as requested

// --- UNIFORMS (Connect these to your host program) ---
uniform sampler2D tDiffuse;      // Background Image
uniform vec2 uResolution;        // Screen resolution (e.g., 1920.0, 1080.0)
uniform float uTime;             // Time in seconds
uniform vec2 uMouse;             // Mouse position (optional interaction)

// --- PLEXUS SETTINGS (Editable Variables) ---
uniform vec3 uColor;             // Color of the plexus (default: 0.2, 0.6, 1.0)
uniform float uGridScale;        // Size of the grid cells (default: 5.0 to 10.0)
uniform float uDotSize;          // Radius of the dots (default: 0.05)
uniform float uLineThickness;    // Thickness of lines (default: 0.002)
uniform float uConnectionDist;   // Max distance to connect dots (default: 0.35)
uniform float uGlowStrength;     // Intensity of the glow (default: 0.5)

varying vec2 vUvScaled;          // From your template

// --- HELPER FUNCTIONS ---

// random hash function (float based)
float hash21(vec2 p) {
    p = fract(p * vec2(234.34, 435.345));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// "Noise Effector": Calculate particle position for a grid ID
vec2 getParticlePos(vec2 id) {
    vec2 n = hash22(id);
    // Animate the point using sine waves (Lissajous-like movement)
    // We use uTime to drive the "Noise Effector"
    float t = uTime * 0.5;

    // Create organic movement
    float x = sin(t * n.x + n.y * 6.28) * 0.4; // Keep inside cell mostly
    float y = cos(t * n.y + n.x * 6.28) * 0.4;

    return vec2(x, y);
}

// Distance to a line segment (a to b)
float distToLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// ... [Insert Shader 1: Common Logic here] ...

void main() {
    vec2 uv = vUvScaled;
    uv.x *= uResolution.x / uResolution.y;

    vec2 st = uv * uGridScale;
    vec2 id = floor(st);
    vec2 localUv = fract(st) - 0.5;

    vec3 linesColor = vec3(0.0);

    // Arrays to store neighbor positions to avoid recalculating
    // GLSL 1.0/ES doesn't support dynamic array sizing well, so we hardcode logic
    // But to keep it "float" based and loopable, we will just re-calculate on fly
    // or use a double loop strategy which is O(9*9) = 81 iterations max per pixel (acceptable for fragment)

    // Optimization: We only need to draw lines from the CURRENT cell's neighbors
    // to THEIR neighbors.

    float minDist = 100.0; // Track closest line for alpha blending
    float alphaAcc = 0.0;  // Accumulate line brightness

    // Loop 1: Find Neighbor A
    for(float j = -1.0; j <= 1.0; j += 1.0) {
        for(float i = -1.0; i <= 1.0; i += 1.0) {
            vec2 offsetA = vec2(i, j);
            vec2 posA = offsetA + getParticlePos(id + offsetA); // Position relative to current pixel

            // Loop 2: Find Neighbor B to connect to A
            // We only check neighbors of A that are also generally visible
            for(float l = -1.0; l <= 1.0; l += 1.0) {
                for(float k = -1.0; k <= 1.0; k += 1.0) {
                    vec2 offsetB = vec2(k, l);

                    // Don't connect to self
                    if(abs(i-k) < 0.1 && abs(j-l) < 0.1) continue;

                    // Optimization: Only check unique pairs to save performance? 
                    // In fragment shader, simple loops are often faster than complex logic.

                    vec2 posB = offsetB + getParticlePos(id + offsetB);

                    // Check physical distance between the two particles
                    vec2 distVector = posA - posB;
                    float particleDist = length(distVector);

                    // If particles are close enough to connect
                    if(particleDist < uConnectionDist) {
                        // Calculate distance from PIXEL to the LINE SEGMENT
                        float d = distToLine(localUv, posA, posB);

                        // Create the line visual
                        // Fade out based on particle distance (plexus behavior)
                        float connectionFade = 1.0 - smoothstep(uConnectionDist * 0.5, uConnectionDist, particleDist);

                        // Draw line with thickness
                        float line = smoothstep(uLineThickness, uLineThickness * 0.5, d);

                        alphaAcc += line * connectionFade;
                    }
                }
            }
        }
    }

    // Clamp opacity
    alphaAcc = clamp(alphaAcc, 0.0, 1.0);
    linesColor = uColor * alphaAcc;

    // Composite Additively
    vec4 bg = texture2D(tDiffuse, vUvScaled);
    gl_FragColor = vec4(bg.rgb + linesColor, 1.0);
}

precision highp float;
// Avoiding integer precision as requested
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- UNIFORMS ---
// bend: Intensity of the warp (-100 to 100 in AE, mapped here roughly -1.0 to 1.0)
uniform float bend; 

// h_dist / v_dist: Horizontal and Vertical Distortion (-1.0 to 1.0)
uniform float h_dist; 
uniform float v_dist; 

// warp_axis: 0.0 = Horizontal, 1.0 = Vertical
uniform float warp_axis; 

// warp_style: Selects the math profile
// 0.0 = Arc
// 1.0 = Arc Lower
// 2.0 = Arc Upper
// 3.0 = Arch
// 4.0 = Bulge
// 5.0 = Shell Lower
// 6.0 = Shell Upper
// 7.0 = Flag
// 8.0 = Wave
// 9.0 = Fish
// 10.0 = Rise
// 11.0 = FishEye
// 12.0 = Inflate
// 13.0 = Twist
// 14.0 = Squeeze
uniform float warp_style;

// --- CONSTANTS ---
const float PI = 3.14159265359;

// Helper to rotate coordinates 90 degrees for Vertical Axis handling
vec2 rotate_coords(vec2 coord, float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c);
}

void main()
{
    // 1. Convert UV [0.0, 1.0] to Signed Normalized Coordinates [-1.0, 1.0]
    // This places (0,0) in the center of the image, making math easier.
    vec2 coord = vUvScaled * 2.0 - 1.0;

    // 2. Apply Horizontal and Vertical Distortion (Perspective/Keystoning)
    // This happens independently of the warp style in the chain.
    // H Distortion: Skews X based on Y. V Distortion: Skews Y based on X.

    // Apply Vertical Distortion (Pinches top/bottom)
    float v_scale = 1.0 - (v_dist * coord.y);
    // Avoid division by zero
    if (abs(v_scale) < 0.001) v_scale = 0.001;
    coord.x /= v_scale;

    // Apply Horizontal Distortion (Pinches left/right)
    float h_scale = 1.0 - (h_dist * coord.x);
    if (abs(h_scale) < 0.001) h_scale = 0.001;
    coord.y /= h_scale;

    // 3. Handle Warp Axis
    // If Vertical (1.0), we rotate the coordinate system 90 degrees 
    // so we can use the same math formulas, then rotate back later.
    bool is_vertical = (warp_axis > 0.5);
    if (is_vertical) {
        coord = vec2(coord.y, coord.x);
    }

    // 4. Apply Warp Styles
    // We modify 'coord' based on the selected style index.

    vec2 warped = coord;
    float dist = length(coord); // Distance from center
    float influence_y = (coord.y + 1.0) * 0.5; // 0.0 at bottom, 1.0 at top
    float influence_x = (coord.x + 1.0) * 0.5; // 0.0 at left, 1.0 at right

    // STYLE: Arc (0.0)
    // Bends the grid into a curve.
    if (warp_style < 0.5) {
        // Offset Y based on Cosine of X to create a curve
        warped.y = coord.y + (bend * (cos(coord.x) - 1.0));
    }
    // STYLE: Arc Lower (1.0)
    // Bends the bottom edge, pins the top edge.
    else if (warp_style < 1.5) {
        // Influence is inverted Y (stronger at bottom -1.0)
        float factor = 1.0 - influence_y; 
        warped.y = coord.y + (bend * factor * (cos(coord.x) - 1.0));
    }
    // STYLE: Arc Upper (2.0)
    // Bends the top edge, pins the bottom edge.
    else if (warp_style < 2.5) {
        float factor = influence_y; 
        warped.y = coord.y + (bend * factor * (cos(coord.x) - 1.0));
    }
    // STYLE: Arch (3.0)
    // Vertical arching. 
    else if (warp_style < 3.5) {
        warped.y = coord.y + (bend * abs(coord.y) * (cos(coord.x) - 1.0));
    }
    // STYLE: Bulge (4.0)
    // Pushes center out.
    else if (warp_style < 4.5) {
        // Power function creates a smoother bulge falloff
        warped = coord * (1.0 - bend * (1.0 - dist));
    }
    // STYLE: Shell Lower (5.0)
    // Widens/Shrinks the bottom width.
    else if (warp_style < 5.5) {
        float width_factor = 1.0 + (bend * (1.0 - influence_y));
        warped.x = coord.x * width_factor;
        // Adjust Y slightly to maintain area curve
        warped.y = coord.y + (bend * 0.2 * (coord.x * coord.x)); 
    }
    // STYLE: Shell Upper (6.0)
    // Widens/Shrinks the top width.
    else if (warp_style < 6.5) {
        float width_factor = 1.0 + (bend * influence_y);
        warped.x = coord.x * width_factor;
        warped.y = coord.y - (bend * 0.2 * (coord.x * coord.x));
    }
    // STYLE: Flag (7.0)
    // Sine wave distortion.
    else if (warp_style < 7.5) {
        warped.y = coord.y + sin(coord.x * 3.0) * bend;
        // Flag usually compresses X slightly
        warped.x = coord.x; 
    }
    // STYLE: Wave (8.0)
    // Similar to flag but pins edges.
    else if (warp_style < 8.5) {
        // Window the sine wave with a parabola so edges are 0
        float window = 1.0 - coord.x * coord.x;
        warped.y = coord.y + sin(coord.x * 5.0) * bend * window;
    }
    // STYLE: Fish (9.0)
    // Expands one side, shrinks the other (Left/Right).
    else if (warp_style < 9.5) {
        float scale = 1.0 + bend * coord.x;
        warped.y = coord.y * scale;
        warped.x = coord.x * (1.0 + bend * 0.5 * abs(coord.y));
    }
    // STYLE: Rise (10.0)
    // Pins one side, lifts the other.
    else if (warp_style < 10.5) {
        warped.y = coord.y + (bend * influence_x);
    }
    // STYLE: FishEye (11.0)
    // Pure radial distortion, more aggressive than bulge.
    else if (warp_style < 11.5) {
        float f = 1.0 + bend * dist * dist;
        warped = coord * f;
    }
    // STYLE: Inflate (12.0)
    // Simulates a balloon.
    else if (warp_style < 12.5) {
        // Sine curve bump in the center
        float z = sqrt(1.0 - clamp(dist * dist, 0.0, 1.0));
        float factor = 1.0 + bend * z; 
        warped = coord / factor; 
    }
    // STYLE: Twist (13.0)
    // Rotates the UVs based on radius.
    else if (warp_style < 13.5) {
        float angle = bend * (1.0 - dist) * 2.0; 
        float s = sin(angle);
        float c = cos(angle);
        warped = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c);
    }
    // STYLE: Squeeze (14.0)
    // Pinches the middle horizontally or vertically.
    else {
        // Scale X based on Y position (hourglass shape)
        float squeeze_factor = 1.0 + bend * (1.0 - coord.y * coord.y);
        warped.x = coord.x / squeeze_factor;
        // Compensate Y to preserve area logic
        warped.y = coord.y * (1.0 + bend * 0.2); 
    }

    // 5. Restore Axis
    // If we swapped axes earlier, we must swap back now.
    if (is_vertical) {
        warped = vec2(warped.y, warped.x);
    }

    // 6. Convert back to Texture Space [0.0, 1.0]
    vec2 final_uv = warped * 0.5 + 0.5;

    // 7. Bounds check
    // If the distortion pulls pixels from outside the image, return transparent
    if (final_uv.x < 0.0 || final_uv.x > 1.0 || final_uv.y < 0.0 || final_uv.y > 1.0) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
    } else {
        vec4 texel = texture2D(tDiffuse, final_uv);
        gl_FragColor = texel;
    }
}

text./plugins/ccfx/shaders/part-1-backgrounds:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- User Variables ---

// Rotation: The base rotation of the sunburst in degrees.
uniform float rotation; 

// Rotation Offset: Additional static rotation in degrees to control start point.
uniform float rotation_offset;

// Speed: Animation speed. Multiplies with time.
uniform float speed; 

// Dashes: How many rays the sunburst has.
uniform float dashes; 

// Progress: Thickness of the rays (0.0 to 1.0).
uniform float progress; 

// Scale: Controls width (x) and height (y) stretch.
uniform vec2 scale;

// Center: The origin point of the sunburst (0.0 to 1.0). 
// Default: vec2(0.5, 0.5)
uniform vec2 center;

// Swirl: How much to twist the rays. 
// 0.0 = Straight rays. Higher values = More curve.
uniform float swirl;

// Color 1: Color of the odd number rays (Visible).
uniform vec3 color1; 

// Color 2: Color of the even number rays (Transparent Background).
uniform vec3 color2; 

// Time uniform for animation
uniform float uTime;

void main()
{
    // 1. Offset UVs by the Center position
    // We subtract the 'center' uniform instead of hardcoded 0.5
    vec2 centeredUv = vUvScaled - center;

    // 2. Apply Scale
    // Divide by scale to stretch/squash
    centeredUv /= scale;

    // 3. Calculate Polar Coordinates
    // Angle: The direction of the pixel
    // Dist: The distance from the center (used for Swirl)
    float angle = atan(centeredUv.y, centeredUv.x);
    float dist = length(centeredUv);

    // 4. Apply Swirl
    // We modify the angle based on the distance.
    // Pixels further away get rotated more, creating a spiral effect.
    angle += dist * swirl;

    // 5. Apply Rotation Calculations
    // Convert degrees to radians for both rotation variables
    float totalRotation = radians(rotation) + radians(rotation_offset);

    // Add time-based animation
    float animOffset = totalRotation + (speed * uTime);

    // Apply offsets to the current angle
    float finalAngle = angle - animOffset;

    // 6. Normalize angle to 0.0 - 1.0 range
    // We divide by 2*PI (approx 6.2831853)
    float normalizedAngle = fract(finalAngle / 6.2831853);

    // 7. Generate the Sunburst Pattern
    // Frequency determined by dashes
    float fanFrequency = dashes; 

    // We use modulo logic via fract to repeat the pattern
    // The pattern repeats every (1.0 / dashes)
    float stepValue = fract(normalizedAngle * fanFrequency);

    // 8. Determine the Mask
    // 'step' returns 0.0 if stepValue < progress, 1.0 otherwise.
    // If stepValue < progress, it is the "Ray" (Color 1).
    // If stepValue > progress, it is the "Gap" (Color 2).
    float rayMask = step(progress, stepValue);

    // 9. Mix Colors
    // If rayMask is 0.0, we get Color 1. If 1.0, we get Color 2.
    vec3 finalColor = mix(color1, color2, rayMask);

    // 10. Output with Transparency
    // Invert rayMask for Alpha.
    // rayMask 0.0 (Color 1) becomes Alpha 1.0 (Visible)
    // rayMask 1.0 (Color 2) becomes Alpha 0.0 (Transparent)
    gl_FragColor = vec4(finalColor, 1.0 - rayMask);
}

precision highp float;
// precision highp int; // Integers avoided

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- Controls ---

// 0.0: Bubbles, 1.0: Crystals, 2.0: Plates, 3.0: Static Plates, 
// 4.0: Crystallize, 5.0: Pillow, 6.0: Mixed Crystals, 7.0: Tubular, 
// 8.0: Pillow HQ
uniform float uPatternType; 

uniform float uInvert; // 0.0 = No, 1.0 = Yes
uniform float uContrast; // 1.0 default
uniform float uOverflow; // 0.0: Clip, 1.0: Soft Clamp, 2.0: Wrap Back

uniform float uDisperse; // 0.0 to 1.0
uniform float uSize; // Default ~60.0
uniform vec2 uOffset;

// Tiling
uniform float uEnableTiling; // 0.0 or 1.0
uniform vec2 uCellsTiling; // x: Horizontal, y: Vertical

// Evolution
uniform float uEvolution;
uniform float uCycleEvolution; 
uniform float uCycle; 
uniform float uSeed;

// --- Helper Functions ---

// Float-only Modulo
float fmod(float x, float y) {
    return x - y * floor(x / y);
}

vec2 fmod2(vec2 x, vec2 y) {
    return x - y * floor(x / y);
}

// Random Hash Function
vec3 hash3(vec2 p) {
    vec3 q = vec3(dot(p, vec2(127.1, 311.7)), 
                  dot(p, vec2(269.5, 183.3)), 
                  dot(p, vec2(419.2, 371.9)));
    return fract(sin(q) * (43758.5453 + uSeed));
}

// 3D Cellular Noise
vec3 cellularNoise(vec2 uv, float time) {
    vec2 i_st = floor(uv);
    vec2 f_st = fract(uv);

    float m_dist = 10.0;  
    float m_dist2 = 10.0; 
    float m_id = 0.0;

    for (float y = -1.0; y <= 1.0; y += 1.0) {
        for (float x = -1.0; x <= 1.0; x += 1.0) {
            vec2 neighbor = vec2(x, y);

            vec2 tiledCoord = i_st + neighbor;
            if (uEnableTiling > 0.5) {
                 tiledCoord = fmod2(tiledCoord, uCellsTiling);
            }

            vec3 pointHash = hash3(tiledCoord);
            vec2 point = 0.5 + 0.5 * sin(time + 6.2831 * pointHash.xy);
            point = mix(vec2(0.5), point, uDisperse);

            vec2 diff = neighbor + point - f_st;
            float dist = length(diff);

            if (dist < m_dist) {
                m_dist2 = m_dist;
                m_dist = dist;
                m_id = pointHash.z; 
            } else if (dist < m_dist2) {
                m_dist2 = dist;
            }
        }
    }

    return vec3(m_dist, m_dist2, m_id);
}

void main() {
    // 1. Setup Coordinates
    vec2 uv = vUvScaled;
    uv += uOffset;

    if (uEnableTiling > 0.5) {
        uv *= uCellsTiling;
    } else {
        uv *= (uSize / 10.0); 
    }

    // 2. Evolution
    float time = uEvolution;
    if (uCycleEvolution > 0.5 && uCycle > 0.0) {
         time = fmod(time, uCycle);
    }

    // 3. Generate Noise
    vec3 noise = cellularNoise(uv, time);
    float f1 = noise.x;
    float f2 = noise.y;
    float cellID = noise.z;

    // 4. Pattern Generation
    float val = 0.0;

    if (uPatternType < 0.5) { 
        // Bubbles
        val = 1.0 - f1;
    } 
    else if (uPatternType < 1.5) { 
        // Crystals
        val = f1;
    } 
    else if (uPatternType < 2.5) { 
        // Plates
        val = cellID;
    } 
    else if (uPatternType < 3.5) { 
        // Static Plates
        vec2 staticGrid = floor(uv);
        if (uEnableTiling > 0.5) staticGrid = fmod2(staticGrid, uCellsTiling);
        val = hash3(staticGrid).z; 
    }
    else if (uPatternType < 4.5) { 
        // Crystallize: Raw Gradient
        val = f2 - f1;
    }
    else if (uPatternType < 5.5) { 
        // Pillow (Regular): Gradient shape * Random Cell ID
        float shape = 1.0 - (f2 - f1);
        val = shape * cellID; 
    }
    else if (uPatternType < 6.5) { 
        // Mixed Crystals
        val = (f1 + cellID) * 0.5;
    }
    else if (uPatternType < 7.5) { 
        // Tubular
        val = (f1 + f2) * 0.5;
    }
    else { 
        // Pillow HQ (Fixed): 
        // Uses f2-f1 (Distance to edge)
        // smoothstep creates a hard cut: 0.0 at edge, 1.0 inside.
        // This results in Solid White Cells with Black Borders.
        val = smoothstep(0.0, 0.1, f2 - f1);
    }

    // 5. Contrast
    val = (val - 0.5) * uContrast + 0.5;

    // 6. Overflow
    if (uOverflow < 0.5) {
        val = clamp(val, 0.0, 1.0);
    } 
    else if (uOverflow < 1.5) {
        val = smoothstep(0.0, 1.0, val);
    } 
    else {
        float temp = abs(val);
        temp = fmod(temp, 2.0);
        if (temp > 1.0) temp = 2.0 - temp;
        val = temp;
    }

    // 7. Invert
    if (uInvert > 0.5) {
        val = 1.0 - val;
    }

    gl_FragColor = vec4(vec3(val), 1.0);
}

text./plugins/ccfx/shaders/part-1-distort-pud:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

uniform float u_time;

// --- User Defined Variables ---

uniform float amplitude; 
uniform float frequency; 
uniform float relHeight; 
uniform float rotatePuddle; 
uniform vec2 center; 
uniform float phaseStart; 
uniform float phaseSpeed; 
uniform float innerRadius; 
uniform float innerSoftness; 
uniform float outerRadius; 
uniform float outerSoftness; 

// New Uniform for Edge Handling
// 0: Clamp, 1: Repeat, 2: Mirror, 3: Transparent
uniform int edgeBehavior; 

// Helper function to rotate coordinates
vec2 rotate(vec2 v, float a) {
    float s = sin(radians(a));
    float c = cos(radians(a));
    mat2 m = mat2(c, -s, s, c);
    return m * v;
}

void main()
{
    // --- 1. Coordinate Setup ---
    vec2 p = vUvScaled - 0.5 - center;
    p = rotate(p, rotatePuddle);

    vec2 stretchedP = p;
    stretchedP.y /= max(relHeight, 0.001);

    float dist = length(stretchedP);

    // --- 2. Mask Calculation ---
    float inMask = smoothstep(innerRadius, innerRadius + innerSoftness, dist);
    float outMask = 1.0 - smoothstep(outerRadius, outerRadius + outerSoftness, dist);
    float finalMask = inMask * outMask;

    // --- 3. Wave & Offset Calculation ---
    float currentPhase = phaseStart + (u_time * phaseSpeed);
    float wave = sin((dist * frequency * 10.0) - currentPhase);

    vec2 dir = (dist > 0.0) ? (stretchedP / dist) : vec2(0.0);
    vec2 offset = dir * wave * amplitude * finalMask;

    // --- 4. Apply Offset ---
    vec2 finalUv = vUvScaled + offset;

    // --- 5. Edge Behavior Logic ---
    vec4 color;

    if (edgeBehavior == 1) {
        // Repeat (Wrap)
        finalUv = fract(finalUv);
        color = texture2D(tDiffuse, finalUv);
    } 
    else if (edgeBehavior == 2) {
        // Mirror (Triangle Wave)
        // This calculates a ping-pong effect for coordinates outside 0-1
        finalUv = 1.0 - abs(fract(finalUv * 0.5) * 2.0 - 1.0);
        color = texture2D(tDiffuse, finalUv);
    } 
    else if (edgeBehavior == 3) {
        // Transparent
        if (finalUv.x < 0.0 || finalUv.x > 1.0 || finalUv.y < 0.0 || finalUv.y > 1.0) {
            color = vec4(0.0);
        } else {
            color = texture2D(tDiffuse, finalUv);
        }
    } 
    else {
        // Clamp (Default)
        finalUv = clamp(finalUv, 0.0, 1.0);
        color = texture2D(tDiffuse, finalUv);
    }

    gl_FragColor = color;
}

text./plugins/ccfx/shaders/part-1-distort-ske:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- Editable Uniforms ---
uniform float u_skewStrength;    
uniform float u_skewAngle;      // Now treated as DEGREES
uniform vec2 u_resolution;      
uniform vec2 u_tileOffset;      
uniform float u_mirrorEdges;    // 1.0 for mirrored, 0.0 for repeat

void main()
{
    // 1. Aspect Correction
    vec2 uv = vUvScaled - 0.5;
    float aspect = u_resolution.x / u_resolution.y;
    uv.x *= aspect;

    // 2. Calculate Skew
    // --- CHANGE: Convert degrees to radians here ---
    float angleRad = radians(u_skewAngle); 
    vec2 skewDir = vec2(cos(angleRad), sin(angleRad));

    vec2 perpDir = vec2(-skewDir.y, skewDir.x);
    float skewFactor = dot(uv, perpDir) * u_skewStrength;

    // 3. Displacement
    // We keep the original vUvScaled as the base to maintain orientation
    vec2 skewedUv = vUvScaled + (skewDir * skewFactor) + u_tileOffset;

    // 4. MIRROR TILE LOGIC (Fixed for Orientation)
    vec2 finalUv;

    if (u_mirrorEdges > 0.5) {
        // Improved Mirror Formula: 
        // This version ensures that at skewedUv = 0.5, finalUv is 0.5 (no flip)
        vec2 m = mod(skewedUv, 2.0);
        finalUv.x = m.x > 1.0 ? 2.0 - m.x : m.x;
        finalUv.y = m.y > 1.0 ? 2.0 - m.y : m.y;

        // Safety: ensure no edge-case values hit 1.0/0.0 exactly in a way that flips
        finalUv = clamp(finalUv, 0.001, 0.999);
    } else {
        // Standard Repeat
        finalUv = fract(skewedUv);
    }

    // 5. Sample the texture
    gl_FragColor = texture2D(tDiffuse, finalUv);
}

text./plugins/ccfx/shaders/part-1-distort-war:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
uniform float uTime; 

varying vec2 vUvScaled;

// Original variables
uniform float uAmplitude;      
uniform float uFrequency;      
uniform float uAngle;          
uniform float uDisplaceAngle;  
uniform float uPhaseStart;     
uniform float uPhaseSpeed;     

// New variables
uniform bool uMirrorEdges; // Toggle: True = Mirror/Motion Tile, False = Clamp

void main()
{
    float angleRad = radians(uAngle);
    float displaceRad = radians(uAngle + uDisplaceAngle);

    vec2 dir = vec2(cos(angleRad), sin(angleRad));
    vec2 displaceDir = vec2(cos(displaceRad), sin(displaceRad));

    float wavePos = dot(vUvScaled, dir) * uFrequency;
    float totalPhase = uPhaseStart + (uTime * uPhaseSpeed);

    float wave = sin(wavePos + totalPhase) * uAmplitude;

    // Calculate the distorted UV
    vec2 distortedUv = vUvScaled + (displaceDir * wave);

    // --- UV Handling (Mirror vs Clamp) ---
    vec2 finalUv;

    if (uMirrorEdges) {
        // Motion Tile Logic: Reflects the UVs back and forth
        // abs(1.0 - mod(abs(uv), 2.0)) creates a 0->1->0 mirrored loop
        finalUv = abs(mod(distortedUv - 1.0, 2.0) - 1.0);
    } else {
        // Simple Clamp Logic: Keeps UVs within [0.0, 1.0]
        finalUv = clamp(distortedUv, 0.0, 1.0);
    }

    vec4 texel = texture2D(tDiffuse, finalUv);
    gl_FragColor = texel;
}

text./plugins/ccfx/shaders/part-1-transitions:
precision highp float;
precision highp int;

// Inputs
uniform sampler2D tDiffuse; // The "From" input
uniform sampler2D tTo;      // The "To" input
varying vec2 vUvScaled;

// UI Variables
uniform float wipe_percent;     // Range: 0.0 to 1.0
uniform float checkers_mode;    // 0.0 = Shrink, 1.0 = Grow
uniform float edge_softness;    // Default: 0.0 (Now acts as Border Width)
uniform float angle;            // Default: 45.0
uniform float frequency;        // Default: 6.0
uniform float rel_width;        // Default: 1.0
uniform float rel_wid_pre_rot;  // Default: 1.0
uniform vec2  shift;            // Default: [0.0, 0.0]
uniform float grad_add;         // Default: 0.0
uniform float grad_angle;       // Default: 0.0
uniform vec3  trans_color;      // Default: [0.0, 0.0, 0.0]

// Helper: Rotate UV coordinates
vec2 rotate_uv(vec2 uv, float rotation) {
    float rad = radians(rotation);
    float c = cos(rad);
    float s = sin(rad);
    return vec2(uv.x * c - uv.y * s, uv.x * s + uv.y * c);
}

void main() {
    // 1. Prepare Base Coordinates
    vec2 p = vUvScaled - vec2(0.5);

    // 2. Apply Transformations
    p.x /= max(0.0001, rel_wid_pre_rot);
    p = rotate_uv(p, angle);
    p.x /= max(0.0001, rel_width);
    p -= shift;
    p *= frequency;

    // 3. Create Grid/Tile Logic
    vec2 tile_uv = fract(p);

    // Distance from center of tile (0.0 center -> 1.0 edge)
    float dist = max(abs(tile_uv.x - 0.5), abs(tile_uv.y - 0.5)) * 2.0;

    // 4. Calculate Thresholds (Timing)
    // Project UV onto gradient vector
    vec2 grad_dir = vec2(cos(radians(grad_angle)), sin(radians(grad_angle)));
    float grad_pos = dot(vUvScaled - vec2(0.5), grad_dir);
    float grad_offset = grad_pos * grad_add;

    // Border width is defined by edge_softness
    float border_width = max(0.0, edge_softness);

    // Calculate spread to ensure the animation clears the screen
    float spread = 1.0 + abs(grad_add) + border_width;

    // The "Main Edge" is the outer boundary of the transition
    float main_edge = (wipe_percent * spread) - (abs(grad_add) * 0.5) - grad_offset;

    // The "Inner Edge" is the Main Edge minus the border width
    float inner_edge = main_edge - border_width;

    // 5. Calculate Masks
    // Define a small smoothing factor for anti-aliasing (prevents jagged pixels)
    float smoothing = 0.02;

    // Mask 1: The "Hole" in the center (Inside the inner edge)
    // 1.0 if inside the inner hole, 0.0 if outside
    float inner_mask = 1.0 - smoothstep(inner_edge, inner_edge + smoothing, dist);

    // Mask 2: The "Total Shape" (Inside the outer edge)
    // 1.0 if inside the outer edge, 0.0 if outside
    float outer_mask = 1.0 - smoothstep(main_edge, main_edge + smoothing, dist);

    // The Border is the difference between the Total Shape and the Hole
    float border_mask = outer_mask - inner_mask;
    border_mask = clamp(border_mask, 0.0, 1.0);

    // 6. Composition
    vec4 from_col = texture2D(tDiffuse, vUvScaled);
    vec4 to_col = texture2D(tTo, vUvScaled);
    vec4 border_col = vec4(trans_color, 1.0);

    vec4 final_color;

    if (checkers_mode > 0.5) {
        // Grow Mode
        // Center (Inner Mask) = Destination Image (Revealing)
        // Outside (1.0 - Outer Mask) = Source Image (Hiding)

        // Start with background (From Image)
        final_color = from_col;

        // Mix in the border
        final_color = mix(final_color, border_col, border_mask);

        // Mix in the center (To Image) on top
        final_color = mix(final_color, to_col, inner_mask);

    } else {
        // Shrink Mode
        // Center (Inner Mask) = Source Image (Shrinking away)
        // Outside (1.0 - Outer Mask) = Destination Image (Revealing background)

        // Start with background (To Image)
        final_color = to_col;

        // Mix in the border
        final_color = mix(final_color, border_col, border_mask);

        // Mix in the center (From Image) on top
        final_color = mix(final_color, from_col, inner_mask);
    }

    gl_FragColor = final_color;
}

precision highp float;
precision highp int;

// --- Input Textures ---
uniform sampler2D tDiffuse; // The Image to be transitioned
uniform sampler2D tTo;      // Unused (but kept for compatibility)

// --- Main Wipe Variables ---
uniform float wipePercent;  // Range: 0 to 1
uniform float dots;         // 0.0 = Grow, 1.0 = Shrink
uniform float invert;       // 0.0 = Normal, 1.0 = Invert Inside/Outside

// --- Dot Pattern Settings ---
uniform float edgeSoftness; // Range: 0 or greater
uniform float angle;        // Range: any
uniform float frequency;    // Range: 0.1 or greater
uniform float relWidth;     // Range: 0.1 or greater
uniform float relWidPreRot; // Range: 0.1 or greater
uniform vec2 shift;         // Range: any

// --- Gradient Settings ---
uniform float gradAdd;      // Range: -10 to 10
uniform float gradAngle;    // Range: any

// --- Border Variables ---
uniform float borderWidth;    // Default: 0, Range: 0 or greater
uniform vec3 borderColor;     // Default: [0.75, 0.0, 0.0]
uniform float borderOpacity;  // Default: 1, Range: 0 to 1
uniform float borderSoftness; // Default: 0, Range: 0 or greater
uniform float borderShift;    // Default: 0, Range: any

varying vec2 vUvScaled;

// --- Helper Functions ---
vec2 rotate(vec2 v, float a) {
    float s = sin(radians(a));
    float c = cos(radians(a));
    mat2 m = mat2(c, -s, s, c);
    return m * v;
}

void main() {
    // 1. Center UVs
    vec2 center = vec2(0.5);
    vec2 uv = vUvScaled - center;

    // 2. Gradient Timing
    float gradientOffset = 0.0;
    if (gradAdd > 0.0) {
        vec2 gradUV = rotate(uv, gradAngle);
        float gradVal = gradUV.x + 0.5; 
        gradientOffset = gradVal * gradAdd;
    }

    // 3. Transform UVs (Squash/Stretch/Rotate)
    uv.x /= max(0.001, relWidPreRot);
    uv = rotate(uv, angle);
    uv.x /= max(0.001, relWidth);

    // 4. Generate Grid
    vec2 gridUV = uv * frequency + shift;
    vec2 cellUV = fract(gridUV) - 0.5;

    // 5. Distance Field
    float dist = length(cellUV);

    // 6. Calculate Radius Logic
    float maxRadius = 0.8; 
    float totalRange = 1.0 + gradAdd;

    // Expand range slightly for borders/softness
    float safeRange = totalRange + edgeSoftness + borderWidth;
    float currentWipe = wipePercent * safeRange;
    float localProgress = currentWipe - gradientOffset;

    float currentRadius;

    // Handle Grow vs Shrink Logic
    if (dots > 0.5) { 
        // --- SHRINK ---
        currentRadius = (1.0 - localProgress) * maxRadius;
    } else { 
        // --- GROW ---
        currentRadius = localProgress * maxRadius;
    }

    // 7. Generate Main Alpha Mask
    float alphaMask;
    float mainStep = smoothstep(currentRadius - edgeSoftness, currentRadius, dist);

    // Apply Invert and Dot Mode Logic
    if (dots > 0.5) {
        // Shrink Mode: Inside(0) = Visible, Outside(1) = Transparent
        if (invert > 0.5) alphaMask = 1.0 - mainStep;
        else alphaMask = mainStep;
    } else {
        // Grow Mode: Inside(0) = Transparent, Outside(1) = Visible
        // Logic: Inside Grow (dist < radius) is the "Wipe" action
        float insideIsWipe = 1.0 - mainStep;

        if (invert > 0.5) alphaMask = 1.0 - insideIsWipe;
        else alphaMask = insideIsWipe;
    }
    // Note: alphaMask here represents "How much of the wipe is complete at this pixel".
    // 0.0 = Show Original Image. 
    // 1.0 = Show Transparency.

    // 8. Generate Border Mask
    float finalBorderMask = 0.0;
    if (borderWidth > 0.0) {
        float borderCenter = currentRadius + borderShift;
        float distFromBorder = abs(dist - borderCenter);
        float halfWidth = borderWidth * 0.5; 
        finalBorderMask = 1.0 - smoothstep(halfWidth, halfWidth + borderSoftness, distFromBorder);
    }

    // 9. Composite Final Image
    vec4 texFrom = texture2D(tDiffuse, vUvScaled);
    vec4 transparent = vec4(0.0, 0.0, 0.0, 0.0);

    // Mix Image with Transparency
    // alphaMask 0 -> texFrom
    // alphaMask 1 -> transparent
    vec4 baseColor = mix(texFrom, transparent, clamp(alphaMask, 0.0, 1.0));

    // Apply the Border
    // The border is solid color mixed on top of the base
    vec4 borderColWithAlpha = vec4(borderColor, 1.0);

    // We mix the baseColor with the Border Color using the borderMask
    gl_FragColor = mix(baseColor, borderColWithAlpha, finalBorderMask * borderOpacity);
}

// Background Color: Default: [1 0 0 1]
// The color to wipe to (Red by default). Format is R G B A.

precision highp float;
precision highp int;

uniform sampler2D tDiffuse; 
varying vec2 vUvScaled;

// --- User Variables ---
uniform float wipePercent;    // Default: 0, Range: 0 to 1
uniform float edgeSoftness;   // Default: 0, Range: 0 or greater
uniform float frequency;      // Default: 4, Range: 0.1 or greater
uniform float relWidth;       // Default: 1, Range: 0.1 or greater
uniform float shiftStripes;   // Default: 0, Range: -5 to 5
uniform vec2 center;          // Default: [0 0]
uniform float bulge;          // Default: 0, Range: -1 to 1
uniform float rotate;         // Default: 0
uniform float gradAdd;        // Default: 0, Range: -10 to 10
uniform float gradAngle;      // Default: 0
uniform float radialGrad;     // Default: 0

uniform vec4 backgroundColor; 

#define PI 3.14159265359

void main() {
    // 1. Normalize Coordinates
    vec2 p = vUvScaled - 0.5 - center;

    // 2. Apply Rotation
    float rad = radians(rotate);
    float c = cos(rad);
    float s = sin(rad);
    p = mat2(c, -s, s, c) * p;

    // 3. Apply Relative Width
    p.x /= max(0.001, relWidth); 

    // 4. Calculate Distance and Bulge
    float dist = length(p);
    float distExp = 1.0;
    if (bulge >= 0.0) {
        distExp = 1.0 + bulge; 
    } else {
        distExp = 1.0 / (1.0 + abs(bulge));
    }
    dist = pow(dist, distExp);

    // 5. Generate Ring Pattern (Range: 0.0 to 1.0)
    float rings = 0.5 + 0.5 * cos((dist * frequency * 2.0 * PI) + shiftStripes);

    // 6. Calculate Gradients
    float rGrad = dist * radialGrad;
    float gRad = radians(gradAngle);
    float lGrad = (p.x * cos(gRad) + p.y * sin(gRad)) * gradAdd;

    // 7. Combine for Master Timing Map
    float map = rings + rGrad + lGrad;

    // --- FIX: DYNAMIC RANGE SWEEP ---
    // Calculate the distance to the farthest possible corner based on the user's center offset.
    // This ensures we know exactly how far the gradient values stretch.
    vec2 maxCorner = vec2(0.5) + abs(center);
    float maxDist = length(maxCorner);

    // Calculate the maximum possible influence of the gradients
    float gradMag = (abs(radialGrad) * maxDist) + (abs(gradAdd) * maxDist);

    // Determine the absolute Minimum and Maximum values the "map" can possibly reach.
    // The rings are 0.0 to 1.0. The gradients subtract or add 'gradMag'.
    float mapMin = 0.0 - gradMag; 
    float mapMax = 1.0 + gradMag; 

    // Calculate the Threshold Range
    // We want the Wipe to travel from [Min - Softness] to [Max + Softness]
    // This guarantees the threshold fully clears the map at both ends.
    float startT = mapMin - edgeSoftness - 0.001;
    float endT = mapMax + edgeSoftness + 0.001;

    // Linearly interpolate the threshold based on wipePercent
    float threshold = mix(startT, endT, wipePercent);

    // 8. Compute Alpha
    // If map > threshold, we see Image (1.0). If map < threshold, we see Background (0.0).
    float alphaVal = smoothstep(threshold - edgeSoftness, threshold, map);

    // 9. Output Mix
    vec4 texFrom = texture2D(tDiffuse, vUvScaled);
    gl_FragColor = mix(backgroundColor, texFrom, vec4(alphaVal));
}

precision highp float;
precision highp int;

// --- Input Textures ---
uniform sampler2D tDiffuse; // The "From" image
uniform sampler2D tTo;      // The "To" image (Added for transition logic)

// --- Wipe Variables ---
uniform float wipePercent;  // Default: 0, Range: 0 to 1
uniform float edgeSoftness; // Default: 0, Range: 0 or greater
uniform float angle;        // Default: 45, Range: any
uniform float frequency;    // Default: 6, Range: 0.1 or greater
uniform float shiftStripes; // Default: 0, Range: any
uniform float gradAdd;      // Default: 0, Range: -10 to 10
uniform float gradAngle;    // Default: 0, Range: any

// --- Border Variables ---
uniform float borderWidth;    // Default: 0, Range: 0 or greater
uniform vec3 borderColor;     // Default: [0.75, 0.0, 0.0]
uniform float borderOpacity;  // Default: 1, Range: 0 to 1
uniform float borderSoftness; // Default: 0, Range: 0 or greater
uniform float borderShift;    // Default: 0, Range: any

varying vec2 vUvScaled;

// --- Helper Functions ---

vec2 rotate(vec2 v, float a) {
    float s = sin(radians(a));
    float c = cos(radians(a));
    mat2 m = mat2(c, -s, s, c);
    return m * v;
}

void main()
{
    vec2 center = vec2(0.5);
    vec2 uv = vUvScaled - center;

    // 1. Generate Stripe Pattern
    vec2 stripeUV = rotate(uv, angle);
    // Create sawtooth wave (0.0 to 1.0)
    float pattern = fract(stripeUV.x * frequency + shiftStripes);

    // 2. Calculate Gradient (for Progressive Wipes)
    float gradientVal = 0.0;
    if (gradAdd != 0.0) {
        vec2 gradUV = rotate(uv, gradAngle);
        gradientVal = gradUV.x + 0.5; 
    }

    // 3. Create the Main Mask
    float combinedMask = pattern + (gradientVal * gradAdd);

    // 4. Calculate Thresholds
    // Range must cover 1.0 + gradAdd, plus room for softness and border
    float totalRange = 1.0 + abs(gradAdd); 
    // We expand the total travel distance slightly so the border clears the screen fully
    float currentThreshold = wipePercent * (totalRange + edgeSoftness + borderWidth);

    // 5. Main Wipe Logic
    // Smoothstep creates the gradient for edge softness
    float mixVal = smoothstep(currentThreshold - edgeSoftness, currentThreshold, combinedMask);
    float finalMix = 1.0 - mixVal;

    // 6. Border Logic
    float borderMask = 0.0;
    if (borderWidth > 0.0) {
        // Find distance from the current cut line (threshold)
        // Apply Border Shift here
        float dist = abs(combinedMask - (currentThreshold + borderShift));

        // Create the band: 1.0 at center, fading out to borderWidth
        // We use smoothstep inverted to create the fade
        float outerEdge = borderWidth + borderSoftness;
        borderMask = 1.0 - smoothstep(borderWidth, outerEdge, dist);
    }

    // 7. Composite
    vec4 texFrom = texture2D(tDiffuse, vUvScaled);
    vec4 texTo = texture2D(tTo, vUvScaled);

    // Mix the two images based on the Wipe
    vec4 baseColor = mix(texFrom, texTo, finalMix);

    // Apply the Border on top
    // We mix the baseColor with the Border Color based on the mask and opacity
    gl_FragColor = mix(baseColor, vec4(borderColor, 1.0), borderMask * borderOpacity);
}

text./plugins/ccfx/shaders/part-2-cc-light-sw:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --- User Defined Variables ---
// Adjusts the angle at which the light sweep moves
uniform float Direction; 

// Controls how bright the light sweep appears
uniform float SweepIntensity;

// 0.0 = Linear Sweep, 1.0 = Circular Sweep
uniform float Shape;

// Modifies the brightness at the edge of the light sweep
uniform float EdgeIntensity;

// Adjusts the thickness of the light sweep edge
uniform float EdgeThickness;

// Color of the light sweep
uniform vec3 LightColor;

// 0.0 = Add, 1.0 = Composite, 2.0 = Cutout
uniform float LightReception;

// Center position of the sweep (Required for rotation/positioning)
uniform vec2 Center;

// Width of the light beam (Added to ensure the sweep has visibility)
uniform float BeamWidth;


void main()
{
  vec4 texel = texture2D(tDiffuse, vUvScaled);
  float alpha = texel.a;

  // --- 1. Calculate Sweep Geometry ---
  vec2 coord = vUvScaled - Center;
  float dist = 0.0;

  if (Shape < 0.5) {
      // Linear Sweep: Rotate coordinates to find distance from the "beam" line
      // Converting degrees to radians
      float rad = radians(Direction);
      float s = sin(-rad); // Negative to align rotation with standard clockwise feel
      float c = cos(-rad);

      // Rotate the coordinate system relative to center
      vec2 rotated = vec2(coord.x * c - coord.y * s, coord.x * s + coord.y * c);

      // Distance is the absolute width from the center line
      dist = abs(rotated.x);
  } else {
      // Circular Sweep: Distance is simply length from center
      dist = length(coord);
  }

  // Create the beam profile (Soft edge falloff)
  // 1.0 at the center, fading to 0.0 at BeamWidth
  float beam = 1.0 - smoothstep(0.0, BeamWidth, dist);


  // --- 2. Top-Left Edge Detection ---
  // To highlight top-left edges, we look at neighbors in the top-left direction.
  // We offset the UV lookup by the EdgeThickness.

  // Scale thickness to a small UV offset (avoiding integers)
  float thicknessScale = 0.002; 
  vec2 offsetDirection = vec2(-1.0, 1.0); // Left and Up (Assuming Y is Up)
  vec2 offset = offsetDirection * EdgeThickness * thicknessScale;

  // Sample the alpha of the neighbor
  float neighborAlpha = texture2D(tDiffuse, vUvScaled + offset).a;

  // Calculate Edge Factor: 
  // We want pixels that are opaque (current alpha) but have transparent neighbors (neighbor alpha).
  // max(0.0, ...) ensures we only highlight the "lit" side (Top-Left) and not the shadowed side.
  float edgeFactor = max(0.0, alpha - neighborAlpha);


  // --- 3. Combine Lights ---
  // Calculate the individual light components
  vec3 sweepLight = LightColor * beam * SweepIntensity;

  // The edge highlight is also masked by the sweep "beam" so it moves with the light
  vec3 edgeLight = LightColor * edgeFactor * EdgeIntensity * beam;

  // Total light to apply
  vec3 totalLight = sweepLight + edgeLight;


  // --- 4. Light Reception ---
  vec4 finalColor = vec4(0.0);

  // Mask light to the image's alpha channel
  vec3 litRGB = totalLight * alpha;

  if (LightReception < 0.5) {
      // Add Mode: Adds light purely to the image (can blow out to white)
      finalColor.rgb = texel.rgb + litRGB;
      finalColor.a = alpha;

  } else if (LightReception < 1.5) {
      // Composite Mode: Blends light using Screen logic (softer, preserves details better than Add)
      // Screen = 1.0 - (1.0 - Base) * (1.0 - Blend)
      finalColor.rgb = 1.0 - (1.0 - texel.rgb) * (1.0 - litRGB);
      finalColor.a = alpha;

  } else {
      // Cutout Mode: Shows only the light sweep
      finalColor.rgb = litRGB;
      finalColor.a = alpha;
  }

  gl_FragColor = finalColor;
}

text./plugins/ccfx/shaders/part-2-lens-flare-:
precision highp float;

// --------------------------------------------------------------------------
// VARYINGS & INPUTS
// --------------------------------------------------------------------------
uniform sampler2D tDiffuse;
varying vec2 vUvScaled;

// --------------------------------------------------------------------------
// UNIFIED EDITABLE PARAMETERS (UNIFORMS)
// --------------------------------------------------------------------------

// --- GLOBAL CONTROLS ---
// 0.0 = Anamorphic, 1.0 = Geometric, 2.0 = Orbs
uniform float uMode;             

uniform vec2 uResolution;        // Canvas resolution (width, height)
uniform vec2 uFlarePosition;     // 0.0 to 1.0 (0.5, 0.5 is center)
uniform float uFlareBrightness;  // Global Brightness Multiplier
uniform vec3 uFlareColor;        // Global Color Tint

// --- MODE 0 SPECIFIC (Anamorphic) ---
uniform float uAnamorphicStretch;    // Width. Range: 0.0 to 3.0 (Multiplied internally)
uniform float uAnamorphicHeight;     // NEW: Thickness. Range: 5.0 (Thick) to 50.0 (Thin)
uniform float uAnamorphicBrightness; // Brightness.
uniform float uGhostDispersal;       // Spread of ghosts.

// --- MODE 1 SPECIFIC (Geometric) ---
uniform float uTime;             

// --- MODE 2 SPECIFIC (Orbs) ---
uniform float uScale;            
uniform float uDistortion;       

// --------------------------------------------------------------------------
// MODE 0 HELPER FUNCTIONS (Anamorphic & Ghosts)
// --------------------------------------------------------------------------

vec3 genAnamorphicShape(vec2 uv, float stretch, float thickness, float brightness) {
    // 1. Safety max to prevent division by zero
    float safeStretch = max(stretch, 1.0); 
    float safeThickness = max(thickness, 1.0);

    vec2 scaledUv = uv;

    // 2. Horizontal Stretch
    scaledUv.x /= safeStretch; 

    // 3. Vertical Thickness (Height)
    // Controlled by the new uAnamorphicHeight uniform
    scaledUv.y *= safeThickness; 

    // 4. Gradient Generation
    // Increased base radius from 0.2 to 0.5 to allow longer tails
    float streak = smoothstep(0.5, 0.0, length(scaledUv));

    // 5. Sharpening
    // Reduced power from 4.0 to 3.0 to keep the streak visible longer
    streak = pow(streak, 3.0);

    return vec3(streak) * brightness;
}

vec3 lensflaresMode0(vec2 uv, vec2 pos, float dispersal) {
    vec2 mainVec = uv - pos;
    vec2 uvd = uv * (length(uv));
    float ang = atan(mainVec.y, mainVec.x);
    float dist = length(mainVec);
    dist = pow(dist, 0.1);

    // Sun Glow
    float f0 = 1.0 / (length(uv - pos) * 25.0 + 1.0);
    f0 = pow(f0, 2.0);
    f0 = f0 + f0 * (sin((ang + 1.0 / 18.0) * 12.0) * 0.1 + dist * 0.1 + 0.8);

    // Ghosts
    float f2  = max(1.0 / (1.0 + 32.0 * pow(length(uvd + 0.8 * dispersal * pos), 2.0)), 0.0) * 0.25;
    float f22 = max(1.0 / (1.0 + 32.0 * pow(length(uvd + 0.85 * dispersal * pos), 2.0)), 0.0) * 0.23;
    float f23 = max(1.0 / (1.0 + 32.0 * pow(length(uvd + 0.9 * dispersal * pos), 2.0)), 0.0) * 0.21;

    vec2 uvx = mix(uv, uvd, -0.5);
    float f4  = max(0.01 - pow(length(uvx + 0.4 * dispersal * pos), 2.4), 0.0) * 6.0;
    float f42 = max(0.01 - pow(length(uvx + 0.45 * dispersal * pos), 2.4), 0.0) * 5.0;
    float f43 = max(0.01 - pow(length(uvx + 0.5 * dispersal * pos), 2.4), 0.0) * 3.0;

    uvx = mix(uv, uvd, -0.4);
    float f5  = max(0.01 - pow(length(uvx + 0.2 * dispersal * pos), 5.5), 0.0) * 2.0;
    float f52 = max(0.01 - pow(length(uvx + 0.4 * dispersal * pos), 5.5), 0.0) * 2.0;
    float f53 = max(0.01 - pow(length(uvx + 0.6 * dispersal * pos), 5.5), 0.0) * 2.0;

    uvx = mix(uv, uvd, -0.5);
    float f6  = max(0.01 - pow(length(uvx - 0.3 * dispersal * pos), 1.6), 0.0) * 6.0;
    float f62 = max(0.01 - pow(length(uvx - 0.325 * dispersal * pos), 1.6), 0.0) * 3.0;
    float f63 = max(0.01 - pow(length(uvx - 0.35 * dispersal * pos), 1.6), 0.0) * 5.0;

    vec3 lensflare = vec3(f2 + f4 + f5 + f6, f22 + f42 + f52 + f62, f23 + f43 + f53 + f63);
    return vec3(f0) + lensflare;
}

// --------------------------------------------------------------------------
// MODE 1 HELPER FUNCTIONS (Geometric)
// --------------------------------------------------------------------------
float rnd_float(float w) {
    float f = fract(sin(w) * 1000.0);
    return f;
}
float regShape(vec2 p, float N) {
    float f;
    float a = atan(p.x, p.y) + 0.2;
    float b = 6.28319 / N;
    f = smoothstep(0.5, 0.51, cos(floor(0.5 + a / b) * b - a) * length(p.xy));
    return f;
}
vec3 circleMode1(vec2 p, float size, float decay, vec3 colorInput, vec3 colorInput2, float dist, vec2 mouse) {
    float l = length(p + mouse * (dist * 4.0)) + size / 2.0;
    float c = max(0.01 - pow(length(p + mouse * dist), size * 1.4), 0.0) * 50.0;
    float c1 = max(0.001 - pow(l - 0.3, 1.0 / 40.0) + sin(l * 30.0), 0.0) * 3.0;
    float c2 = max(0.04 / pow(length(p - mouse * dist / 2.0 + 0.09) * 1.0, 1.0), 0.0) / 20.0;
    float s = max(0.01 - pow(regShape(p * 5.0 + mouse * dist * 5.0 + 0.9, 6.0), 1.0), 0.0) * 5.0;
    vec3 col = 0.5 + 0.5 * sin(colorInput);
    col = cos(vec3(0.44, 0.24, 0.2) * 8.0 + dist * 4.0) * 0.5 + 0.5;
    vec3 f = c * col; f += c1 * col; f += c2 * col; f += s * col;
    return f - 0.01;
}

// --------------------------------------------------------------------------
// MODE 2 HELPER FUNCTIONS (Orbs)
// --------------------------------------------------------------------------
#define ORB_FLARE_COUNT 6.0
vec2 GetDistOffset(vec2 uv, vec2 pxoffset) {
    vec2 tocenter = uv.xy;
    vec3 prep = normalize(vec3(tocenter.y, -tocenter.x, 0.0));
    float angle = length(tocenter.xy) * 2.221 * uDistortion;
    vec3 oldoffset = vec3(pxoffset, 0.0);
    vec3 rotated = oldoffset * cos(angle) + cross(prep, oldoffset) * sin(angle) + prep * dot(prep, oldoffset) * (1.0 - cos(angle));
    return rotated.xy;
}
float glareMode2(vec2 uv, vec2 pos, float size) {
    vec2 main = uv - pos;
    float ang = atan(main.y, main.x);
    float dist = length(main); dist = pow(dist, 0.1);
    float f0 = 1.0 / (length(uv - pos) * (1.0 / size * 16.0) + 1.0);
    return f0 + f0 * (sin((ang) * 8.0) * 0.2 + dist * 0.1 + 0.9);
}
vec3 flareMode2Calc(vec2 uv, vec2 pos, float dist, float size) {
    pos = GetDistOffset(uv, pos);
    float r = max(0.01 - pow(length(uv + (dist - 0.05) * pos), 2.4) * (1.0 / (size * 2.0)), 0.0) * 6.0;
    float g = max(0.01 - pow(length(uv +  dist         * pos), 2.4) * (1.0 / (size * 2.0)), 0.0) * 6.0;
    float b = max(0.01 - pow(length(uv + (dist + 0.05) * pos), 2.4) * (1.0 / (size * 2.0)), 0.0) * 6.0;
    return vec3(r, g, b);
}
vec3 flareMode2Color(vec2 uv, vec2 pos, float dist, float size, vec3 color) {
    return flareMode2Calc(uv, pos, dist, size) * color;
}
vec3 orbMode2(vec2 uv, vec2 pos, float dist, float size) {
    vec3 c = vec3(0.0);
    for(float i = 0.0; i < ORB_FLARE_COUNT; i += 1.0) {
        float j = i + 1.0;
        float offset = j / (j + 1.0);
        float colOffset = j / (ORB_FLARE_COUNT * 2.0);
        c += flareMode2Color(uv, pos, dist + offset, size / (j + 0.1), vec3(1.0 - colOffset, 1.0, 0.5 + colOffset));
    }
    c += flareMode2Color(uv, pos, dist + 0.5, 4.0 * size, vec3(1.0)) * 4.0;
    return c / 4.0;
}
vec3 ringMode2(vec2 uv, vec2 pos, float dist) {
    vec2 uvd = uv * (length(uv));
    float r = max(1.0 / (1.0 + 32.0 * pow(length(uvd + (dist - 0.05) * pos), 2.0)), 0.0) * 0.25;
    float g = max(1.0 / (1.0 + 32.0 * pow(length(uvd +  dist         * pos), 2.0)), 0.0) * 0.23;
    float b = max(1.0 / (1.0 + 32.0 * pow(length(uvd + (dist + 0.05) * pos), 2.0)), 0.0) * 0.21;
    return vec3(r, g, b);
}

// --------------------------------------------------------------------------
// MAIN
// --------------------------------------------------------------------------
void main() {
    float aspect = uResolution.x / uResolution.y;

    vec2 uv = vUvScaled - 0.5;
    uv.x *= aspect;

    vec2 mouse = uFlarePosition - 0.5;
    mouse.x *= aspect;

    vec4 original = texture2D(tDiffuse, vUvScaled);
    vec3 flareResult = vec3(0.0);

    // MODE 0: Anamorphic
    if (uMode < 0.5) { 
        // 1. Ghosts
        vec3 flare = lensflaresMode0(uv * 1.5, mouse * 1.5, uGhostDispersal);

        // 2. Anamorphic Streak
        vec3 anflare = genAnamorphicShape(
            uv - mouse, 
            2.0 * uAnamorphicStretch, 
            uAnamorphicHeight, 
            uAnamorphicBrightness
        );

        flareResult = (flare + anflare);

        // Tone mapping
        flareResult = pow(flareResult, vec3(1.0 / 2.2));

    // MODE 1: Geometric
    } else if (uMode < 1.5) {
        vec3 circColor = vec3(0.9, 0.2, 0.1); 
        vec3 circColor2 = vec3(0.3, 0.1, 0.5);

        flareResult = mix(vec3(0.0), vec3(0.0), uv.y) * 3.0 - 0.52 * sin(uTime / 0.4) * 0.1 + 0.2;

        for (float i = 0.0; i < 10.0; i += 1.0) {
            flareResult += circleMode1(uv, pow(rnd_float(i * 2000.0) * 1.0, 2.0) + 1.41, 0.0, circColor + i, circColor2 + i, rnd_float(i * 20.0) * 3.0 + 0.2 - 0.5, mouse);
        }

        float a = atan(uv.y - mouse.y, uv.x - mouse.x);
        flareResult += max(0.1 / pow(length(uv - mouse) * 5.0, 5.0), 0.0) * abs(sin(a * 5.0 + cos(a * 9.0))) / 20.0;
        flareResult += max(0.1 / pow(length(uv - mouse) * 10.0, 1.0 / 20.0), 0.0) + abs(sin(a * 3.0 + cos(a * 9.0))) / 8.0 * (abs(sin(a * 9.0))) / 1.0;
        flareResult += (max(0.1 / pow(length(uv - mouse) * 4.0, 1.0 / 2.0), 0.0) * 4.0) * vec3(0.2, 0.21, 0.3) * 4.0;

        flareResult *= exp(1.0 - length(uv - mouse)) / 5.0;

    // MODE 2: Orbs
    } else {
        flareResult = vec3(glareMode2(uv, mouse, uScale));
        flareResult += flareMode2Calc(uv, mouse, -3.0, 3.0 * uScale);
        flareResult += flareMode2Calc(uv, mouse, -1.0, uScale) * 3.0;
        flareResult += flareMode2Calc(uv, mouse,  0.5, 0.8 * uScale);
        flareResult += flareMode2Calc(uv, mouse, -0.4, 0.8 * uScale);
        flareResult += orbMode2(uv, mouse, 0.0, 0.5 * uScale);
        flareResult += ringMode2(uv, mouse, -1.0) * 0.5 * uScale;
        flareResult += ringMode2(uv, mouse,  1.0) * 0.5 * uScale;
    }

    // Color Tint & Global Brightness
    flareResult *= uFlareColor * uFlareBrightness;

    vec3 finalColor = original.rgb + flareResult;
    gl_FragColor = vec4(finalColor, original.a);
}

text./plugins/ccfx/shaders/part-2-plexus-v1.g:
precision highp float;
precision highp int;

uniform sampler2D tDiffuse; // The background texture (optional)
varying vec2 vUvScaled;     // Use this UV from your template

// --- EDITABLE UNIFORMS (Connect these to your host program) ---
// If you cannot set uniforms, change the "default" values here.
uniform float uTime;                // Time in seconds
uniform vec2 uResolution;           // Canvas resolution (pixels)
uniform float uGridSize;            // Default: 10.0 (Density of the grid)
uniform float uConnDist;            // Default: 0.15 (Max distance for lines)
uniform float uLineThickness;       // Default: 0.002 (Thickness of connections)
uniform float uPointScale;          // Default: 0.005 (Size of the dots)
uniform vec3 uColor1;               // Default: vec3(0.2, 0.6, 1.0) (Cyan)
uniform vec3 uColor2;               // Default: vec3(1.0, 0.2, 0.5) (Pink/Red)

// --- HELPER FUNCTIONS ---

// A pseudo-random function using only floats (No Integers)
// Returns a random vec2 between 0.0 and 1.0
vec2 N22(vec2 p) {
    vec3 a = fract(vec3(p.xyx) * vec3(123.34, 234.34, 345.65));
    a += dot(a, a.yzx + 34.45);
    return fract(vec2(a.x * a.y, a.y * a.z));
}

// Calculate the shortest distance from point P to line segment AB
float DistLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float t = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * t);
}

// Get the moving particle position for a specific grid ID
vec2 GetPoint(vec2 id) {
    vec2 n = N22(id); // Random seed for this cell

    // Animate the point using Sine/Cosine based on time and random offset
    // This creates the "organic" movement seen in the Plexus video
    float x = sin(uTime * 1.0 + n.x * 6.2831) * 0.4;
    float y = cos(uTime * 1.0 + n.y * 6.2831) * 0.4;

    return vec2(x, y);
}

void main() {
    // 1. Setup UVs
    // Use the vUvScaled from your template, adjusted for aspect ratio if needed
    vec2 uv = vUvScaled;
    // (Optional) Fix aspect ratio if vUvScaled is 0-1
    // uv.x *= uResolution.x / uResolution.y; 

    // 2. Setup Background (using tDiffuse from template)
    vec4 col = texture2D(tDiffuse, vUvScaled);
    // Darken background to make Plexus pop
    col.rgb *= 0.2; 

    // 3. Grid Logic
    // Scale UVs to create the grid cells
    vec2 gv = fract(uv * uGridSize) - 0.5; // Local UV inside the cell (-0.5 to 0.5)
    vec2 id = floor(uv * uGridSize);       // Unique ID for each cell

    vec3 plexusColor = vec3(0.0);

    // 4. Neighbor Loop (The core "Plexus" logic)
    // We check the 3x3 surrounding grid cells to find neighbors
    // Note: Using floats for loop counters to avoid Integers as requested
    for(float y = -1.0; y <= 1.0; y += 1.0) {
        for(float x = -1.0; x <= 1.0; x += 1.0) {

            // Offset for the neighbor cell
            vec2 offs = vec2(x, y);

            // Get the unique particle position for that neighbor cell
            // We add the offset to the ID to get the neighbor's ID
            vec2 p = GetPoint(id + offs); 

            // Adjust position: The point 'p' is local to its own cell.
            // We need to move it relative to the current pixel's cell (gv).
            // 'offs' moves us to the neighbor cell, 'p' is the point inside it.
            vec2 pos = offs + p; 

            // --- DRAW DOTS ---
            // Calculate distance from current pixel (gv) to the particle (pos)
            float d = length(gv - pos);
            // Create a soft glowy dot
            float spark = 1.0 / (d * d * 100.0 * (1.0/uPointScale)); // Inverse square falloff
            plexusColor += spark * uColor1;

            // --- DRAW LINES ---
            // To draw lines, we need to check connections between this neighbor 
            // and the OTHER neighbors.

            // We create a nested loop to check distances between points
            for(float j = -1.0; j <= 1.0; j += 1.0) {
                for(float i = -1.0; i <= 1.0; i += 1.0) {
                    vec2 offs2 = vec2(i, j);
                    vec2 p2 = GetPoint(id + offs2);
                    vec2 pos2 = offs2 + p2;

                    // Calculate distance between the two particles
                    float distPoints = length(pos - pos2);

                    // Only draw line if they are close enough (Editable via uConnDist)
                    if(distPoints < uConnDist) {
                        // Calculate distance from PIXEL to the LINE SEGMENT
                        float distToLine = DistLine(gv, pos, pos2);

                        // Draw the line with smooth edges
                        float lineAlpha = smoothstep(uLineThickness, uLineThickness * 0.5, distToLine);

                        // Fade line based on distance between particles (Plexus style)
                        float fade = 1.0 - smoothstep(0.0, uConnDist, distPoints);

                        // Accumulate line color
                        plexusColor += lineAlpha * fade * uColor2 * 0.5;
                    }
                }
            }
        }
    }

    // 5. Composite
    // Add the plexus effect on top of the original texture
    col.rgb += plexusColor;

    gl_FragColor = col;
}

